import React, { useState } from 'react';
import { HardwareSpecs } from '../types';
import { Cpu, Database, HardDrive, Monitor, Zap, Save, MemoryStick, Chip } from 'lucide-react';

interface Props {
  hardware: HardwareSpecs;
  onChange: (hw: HardwareSpecs) => void;
}

const HardwareDetector: React.FC<Props> = ({ hardware, onChange }) => {
  const [detecting, setDetecting] = useState(false);
  const [status, setStatus] = useState<string>("");
  const [npuDetected, setNpuDetected] = useState(false);

  // Helper for staged delays to make status updates visible
  const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  // Heuristic helper to guess VRAM from GPU model name
  const estimateVRAMFromModel = (renderer: string): number => {
    const r = renderer.toLowerCase();

    // High-End Enthusiast (24GB+)
    if (r.includes('4090') || r.includes('3090') || r.includes('7900') || r.includes('titan')) return 24;

    // High-End (16GB - 20GB)
    if (r.includes('4080') || r.includes('4070 ti super') || r.includes('3090') || r.includes('7800') || r.includes('6950') || r.includes('6900') || r.includes('6800')) return 16;

    // Mid-High (12GB)
    if (r.includes('4070') || r.includes('3080') || r.includes('3060') || r.includes('6700') || r.includes('6750')) return 12;

    // Mid-Range (8GB - 10GB)
    if (r.includes('3080') || r.includes('4060') || r.includes('3070') || r.includes('3050') || r.includes('2080') || r.includes('2070') || r.includes('2060 super') || r.includes('1080') || r.includes('1070') || r.includes('6600') || r.includes('6650') || r.includes('5700')) return 8;

    // Entry (4GB - 6GB)
    if (r.includes('2060') || r.includes('1660') || r.includes('1060') || r.includes('1650') || r.includes('6500') || r.includes('5600')) return 6;

    // Default fallback for Discrete GPU if unknown
    return 8;
  };

  const handleAutoDetect = async () => {
    setDetecting(true);

    // --- Step 1: Initialization ---
    setStatus("Initializing scan...");
    await delay(500);

    // --- Step 2: GPU Detection ---
    setStatus("Analyzing GPU capabilities...");
    let gpuInfo = { vendor: 'Unknown', model: '', vram: 0 };
    let rendererString = "";

    // WebGPU attempt
    if ('gpu' in navigator) {
       try {
         // @ts-ignore
         const adapter = await navigator.gpu.requestAdapter();
         if (adapter) {
           const info = await adapter.requestAdapterInfo();
           gpuInfo.vendor = info.vendor || gpuInfo.vendor;
         }
       } catch (e) {
         console.debug("WebGPU access denied or not supported");
       }
    }

    // Canvas fallback
    const canvas = document.createElement('canvas');
    const gl = (canvas.getContext('webgl') || canvas.getContext('experimental-webgl')) as WebGLRenderingContext;
    if (gl) {
      const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
      if (debugInfo) {
        rendererString = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
        gpuInfo.model = rendererString;

        if (rendererString.includes('NVIDIA')) gpuInfo.vendor = 'NVIDIA';
        else if (rendererString.includes('AMD') || rendererString.includes('Radeon')) gpuInfo.vendor = 'AMD';
        else if (rendererString.includes('Intel')) gpuInfo.vendor = 'Intel';
        else if (rendererString.includes('Apple')) gpuInfo.vendor = 'Apple Silicon';
      }
    }
    await delay(800);

    // --- Step 3: NPU & RAM ---
    setStatus("Checking System Memory & NPU...");

    // NPU Detection Logic
    const ua = navigator.userAgent.toLowerCase();
    const isNPU = 
      ua.includes("snapdragon") || 
      rendererString.toLowerCase().includes("adreno") || 
      rendererString.toLowerCase().includes("apple") || 
      rendererString.toLowerCase().includes("npu") ||
      (gpuInfo.vendor === 'Intel' && rendererString.toLowerCase().includes("arc"));

    setNpuDetected(isNPU);

    // RAM Heuristics
    // @ts-ignore
    const deviceMemory = navigator.deviceMemory || 8; 
    await delay(800);

    // --- Step 4: OS & Architecture ---
    setStatus("Identifying Operating System...");
    const isMac = navigator.platform.toLowerCase().includes('mac');
    const isWin = navigator.platform.toLowerCase().includes('win');
    const os = isMac ? 'macOS' : (isWin ? 'Windows' : 'Linux');

    let cpuType = hardware.cpuType;
    if (isMac) cpuType = 'Apple Silicon';
    else if (ua.includes("arm") || ua.includes("aarch64")) cpuType = 'ARM64';
    else cpuType = 'Intel/AMD';
    await delay(600);

    // --- Step 5: Final Calibration ---
    setStatus("Calibrating VRAM estimates...");
    let estimatedVram = 8;

    if (gpuInfo.vendor === 'Apple Silicon') {
        estimatedVram = Math.floor(deviceMemory * 0.7);
    } else if (gpuInfo.vendor === 'NVIDIA' || gpuInfo.vendor === 'AMD') {
        estimatedVram = estimateVRAMFromModel(rendererString);
    } else if (gpuInfo.vendor === 'Intel') {
        estimatedVram = Math.floor(deviceMemory * 0.5);
    }
    await delay(600);

    // Apply Results
    onChange({
      gpuVendor: gpuInfo.vendor !== 'Unknown' ? gpuInfo.vendor : hardware.gpuVendor,
      vram: estimatedVram,
      ram: deviceMemory,
      cpuType: cpuType,
      os: os,
      diskSpace: hardware.diskSpace
    });
    setDetecting(false);
    setStatus("");
  };

  const updateField = (field: keyof HardwareSpecs, value: any) => {
    onChange({ ...hardware, [field]: value });
  };

  const isApple = hardware.gpuVendor === 'Apple Silicon';
  const isIntel = hardware.gpuVendor === 'Intel';
  const isShared = isApple || isIntel;

  return (
    <div className="bg-zinc-900/50 border border-zinc-800 rounded-xl p-6 shadow-xl backdrop-blur-sm relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-600/10 blur-3xl rounded-full -mr-10 -mt-10"></div>

      <div className="flex justify-between items-center mb-6 relative z-10">
        <h2 className="text-xl font-semibold text-white flex items-center gap-2">
          <Monitor className="text-indigo-400" /> System Profile
        </h2>
        <button
          onClick={handleAutoDetect}
          disabled={detecting}
          className="text-xs px-3 py-1.5 rounded-full bg-indigo-500/10 text-indigo-300 hover:bg-indigo-500/20 transition-all border border-indigo-500/20 flex items-center gap-2"
        >
          {detecting ? (
             <><div className="w-3 h-3 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin" /> {status}</>
          ) : (
             <><Zap size={12} /> Auto-Detect Hardware</>
          )}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-5 relative z-10">
        {/* GPU Vendor */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-zinc-400 flex items-center gap-1.5 justify-between">
            <span className="flex items-center gap-1.5"><Monitor size={14} /> GPU Architecture</span>
            {npuDetected && (
              <span className="text-[9px] uppercase tracking-wider text-emerald-400 bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20 flex items-center gap-1">
                <Chip size={10} /> NPU Active
              </span>
            )}
          </label>
          <select
            value={hardware.gpuVendor}
            onChange={(e) => updateField('gpuVendor', e.target.value)}
            className="w-full bg-zinc-950/80 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-zinc-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
          >
            <option value="NVIDIA">NVIDIA (CUDA)</option>
            <option value="AMD">AMD (ROCm)</option>
            <option value="Apple Silicon">Apple Silicon (Metal)</option>
            <option value="Intel">Intel (Arc/iGPU)</option>
            <option value="NPU">Dedicated NPU (Snapdragon/Other)</option>
          </select>
        </div>

        {/* VRAM / Unified Memory */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-zinc-400 flex items-center gap-1.5 justify-between">
            <span className="flex items-center gap-1.5">
                <Database size={14} /> 
                {isApple ? "Unified Memory" : isIntel ? "Shared Memory (VRAM)" : "Video Memory (VRAM)"}
            </span>
            {isShared && (
                <span className="text-[10px] text-indigo-400 bg-indigo-500/10 px-1.5 py-0.5 rounded border border-indigo-500/20">
                    Shared
                </span>
            )}
          </label>
          <div className="relative">
            <input
              type="number"
              value={hardware.vram}
              onChange={(e) => updateField('vram', Number(e.target.value))}
              className="w-full bg-zinc-950/80 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-zinc-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
            />
            <div className="absolute right-3 top-2.5 text-xs text-zinc-600 font-mono">GB</div>
          </div>
        </div>

        {/* RAM */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-zinc-400 flex items-center gap-1.5">
            <HardDrive size={14} /> System RAM
          </label>
          <div className="relative">
            <input
              type="number"
              value={hardware.ram}
              onChange={(e) => updateField('ram', Number(e.target.value))}
              className="w-full bg-zinc-950/80 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-zinc-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
            />
            <div className="absolute right-3 top-2.5 text-xs text-zinc-600 font-mono">GB</div>
          </div>
        </div>

        {/* Disk Space */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-zinc-400 flex items-center gap-1.5">
            <Save size={14} /> Free Disk Space
          </label>
          <div className="relative">
            <input
              type="number"
              value={hardware.diskSpace}
              onChange={(e) => updateField('diskSpace', Number(e.target.value))}
              className="w-full bg-zinc-950/80 border border-zinc-800 rounded-lg px-3 py-2.5 text-sm text-zinc-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
            />
            <div className="absolute right-3 top-2.5 text-xs text-zinc-600 font-mono">GB</div>
          </div>
